//! Music and sound effects. Every note is generated by Emberdeep's built-in
//! synthesizer at runtime; there are no audio assets.
//!
//! - `synth`: oscillators, voices (ADSR, filters, vibrato), echo, limiter.
//! - `seq`: the tracker notation and the real-time song player.
//! - `songs`: the soundtrack; `sfx`: the sound effects; `patches`: instruments.
//! - `engine`: mixes songs (with crossfades) and effects.
//! - `backend` (feature `audio`): plays the engine through rodio on a
//!   background thread. Without the feature, or without an output device,
//!   `Audio` is silent and every call is a cheap no-op.

#[cfg(feature = "audio")]
mod backend;
pub(crate) mod engine;
pub(crate) mod patches;
pub(crate) mod seq;
pub(crate) mod sfx;
pub(crate) mod songs;
pub(crate) mod synth;

